DEF = "alpha beta gamma\nsecond line here\nthird\nfourth line\nfifth\n"


def sh(*a, **kw):
    return subprocess.run(a, capture_output=True, text=True, **kw)


def make_home(name, content=DEF, title="T1", config=None, extra=None):
    home = f"/tmp/hvv_{name}"
