    c = sqlite3.connect(home + "/tui-journal/entries.db")
    c.execute("update entries set content=?, title=? where id=1", (content, title))
    if extra:
        for i, (t, ct) in enumerate(extra, start=2):
            c.execute("insert into entries (id,title,date,content) values (?,?,?,?)",
                      (i, t, "2026-08-%02dT00:00:00+00:00" % min(i, 28), ct))
    c.commit(); c.close()
    if config is not None:
        os.makedirs(home + "/.config/tui-journal", exist_ok=True)
        open(home + "/.config/tui-journal/config.toml", "w").write(config)
    return home


class Ed:
    def __init__(self, name, content=DEF, cols=80, rows=16, config=None, env=None,
                 args="", extra=None, color=True, home=None, enter=True, title="T1"):
        self.sess = "vv" + name
        self.name = name
        self.home = home or make_home(name, content=content, config=config,
                                      extra=extra, title=title)
        sh("tmux", "kill-session", "-t", self.sess)
        e = {"HOME": self.home, "TERM": "xterm-256color"}
        if env:
            e.update(env)
        parts = ["env"]
        if color:
            parts += ["-u", "NO_COLOR"]
        parts += [f"{k}={v!r}" for k, v in e.items()]
        cmd = " ".join(parts) + f" {EXE} {args}; echo __TJEXIT_$?__; sleep 900"
        sh("tmux", "new-session", "-d", "-s", self.sess, "-x", str(cols), "-y", str(rows), cmd)
        time.sleep(1.1)
        if enter:
            self.send("^Enter", 0.5)

    def send(self, k, delay=0.22):
        if k.startswith("^"):
            sh("tmux", "send-keys", "-t", self.sess, k[1:])
        else:
            sh("tmux", "send-keys", "-t", self.sess, "-l", k)
        time.sleep(delay)

    def keys(self, *ks, delay=0.22):
        for k in ks:
            if k.startswith("@s"):
                time.sleep(float(k[2:]))
            else:
                self.send(k, delay)

    def cap(self, esc=False):
        a = ["tmux", "capture-pane", "-p", "-t", self.sess]
        if esc:
            a.insert(2, "-e")
        return sh(*a).stdout.rstrip("\n")

    def show(self, label="", esc=False):
        print(f"----- {label} -----")
        print(self.cap(esc))
        print(f"----- /{label} -----")

    def db(self, eid=1):
        c = sqlite3.connect(self.home + "/tui-journal/entries.db")
        r = c.execute("select content from entries where id=?", (eid,)).fetchone()
        c.close()
        return r[0]

    def save_and_db(self, eid=1, key="^C-s"):
        self.send(key, 0.5)
        return self.db(eid)

    def kill(self):
        sh("tmux", "kill-session", "-t", self.sess)


def run(name, keys, content=DEF, save=True, cols=80, rows=16, show=True, **kw):
    e = Ed(name, content=content, cols=cols, rows=rows, **kw)
    e.keys(*keys)
    if show:
        e.show("SCREEN")
    out = None
    if save:
        out = e.save_and_db()
        print("DB CONTENT:", repr(out))
    e.kill()
    return out


if __name__ == "__main__":
    pass

